(function() {
    function buildNavbar() {
        // Don't run twice
        if (document.getElementById("fisat-modern-header")) return;

        // Inject Plus Jakarta Sans font
        if (!document.querySelector('link[href*="Plus+Jakarta+Sans"]')) {
            var fontLink = document.createElement("link");
            fontLink.rel = "stylesheet";
            fontLink.href = "https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap";
            document.head.appendChild(fontLink);
        }

        // Create header
        var header = document.createElement("header");
        header.id = "fisat-modern-header";

        var inner = document.createElement("div");
        inner.className = "nav-inner";

        // Logo Area
        var logoArea = document.createElement("a");
        logoArea.href = "/";
        logoArea.className = "nav-logo";

        var img = document.createElement("img");
        img.src = "/wp-content/themes/fisat2022/assets/fisat-logo-cropped.png";
        img.alt = "FISAT - Federal Institute of Science and Technology";
        logoArea.appendChild(img);

        inner.appendChild(logoArea);

        // Nav Menu - extract from existing #menu-primary-menu
        var navMenu = document.createElement("ul");
        navMenu.className = "nav-menu";

        var primaryMenu = document.getElementById("menu-primary-menu");
        if (primaryMenu) {
            var items = primaryMenu.querySelectorAll(":scope > li");
            items.forEach(function(item) {
                var li = document.createElement("li");
                if (item.classList.contains("active") || item.classList.contains("current-menu-item")) {
                    li.classList.add("active");
                }

                var link = item.querySelector(":scope > a");
                if (link) {
                    var a = document.createElement("a");
                    a.href = link.getAttribute("href") || "#";
                    var span = link.querySelector("span");
                    a.textContent = span ? span.textContent.trim() : link.textContent.trim();
                    li.appendChild(a);
                }

                // Check for dropdown
                var submenu = item.querySelector(":scope > .dropdown-menu");
                if (submenu) {
                    var dropdown = document.createElement("div");
                    dropdown.className = "nav-dropdown";
                    var subLinks = submenu.querySelectorAll(":scope > li > a, :scope > .dropdown > a");
                    subLinks.forEach(function(sl) {
                        var sa = document.createElement("a");
                        sa.href = sl.getAttribute("href") || "#";
                        var sspan = sl.querySelector("span");
                        sa.textContent = sspan ? sspan.textContent.trim() : sl.textContent.trim();
                        dropdown.appendChild(sa);
                    });
                    if (dropdown.children.length > 0) {
                        li.appendChild(dropdown);
                    }
                }

                navMenu.appendChild(li);
            });
        }

        inner.appendChild(navMenu);

        var actions = document.createElement("div");
        actions.className = "nav-actions";
        actions.style.display = "flex";
        actions.style.gap = "10px";
        actions.style.alignItems = "center";

        // Login Button
        var loginBtn = document.createElement("a");
        loginBtn.href = "https://intranet.fisat.ac.in/";
        loginBtn.target = "_blank";
        loginBtn.className = "btn-outline";
        loginBtn.style.border = "1px solid var(--accent)";
        loginBtn.style.color = "var(--accent)";
        loginBtn.style.padding = "0.4rem 1rem";
        loginBtn.style.borderRadius = "50px";
        loginBtn.style.fontWeight = "600";
        loginBtn.style.fontSize = "0.85rem";
        loginBtn.style.textDecoration = "none";
        loginBtn.textContent = "Login";
        actions.appendChild(loginBtn);

        // CTA Button
        var ctaBtn = document.createElement("a");
        ctaBtn.href = "/contact/index.html";
        ctaBtn.className = "nav-cta";
        ctaBtn.textContent = "Contact Us";
        actions.appendChild(ctaBtn);

        inner.appendChild(actions);

        // Mobile Toggle
        var toggle = document.createElement("button");
        toggle.className = "nav-toggle";
        toggle.innerHTML = '<i class="fa-solid fa-bars"></i>';
        toggle.addEventListener("click", function() {
            navMenu.classList.toggle("open");
        });
        inner.insertBefore(toggle, navMenu);

        header.appendChild(inner);
        document.body.insertBefore(header, document.body.firstChild);

        // Hide old navbar
        var oldNav = document.getElementById("navBar");
        if (oldNav) {
            oldNav.style.display = "none";
        }
    }

    // Run when DOM is ready
    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", buildNavbar);
    } else {
        buildNavbar();
    }
})();
